insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types)values('resumes','resumes',false,5242880,array['application/pdf','application/msword','application/vnd.openxmlformats-officedocument.wordprocessingml.document']),('attachments','attachments',false,5242880,array['application/pdf','image/jpeg','image/png'])on conflict(id) do update set public=false,file_size_limit=excluded.file_size_limit,allowed_mime_types=excluded.allowed_mime_types;
